import{_ as o,o as t,c as a,ag as d}from"./chunks/framework.TQKaXlFR.js";const u=JSON.parse('{"title":"低代码表单与记录","description":"","frontmatter":{},"headers":[],"relativePath":"features/lowcode.md","filePath":"features/lowcode.md"}'),r={name:"features/lowcode.md"};function c(i,e,s,l,n,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="低代码表单与记录" tabindex="-1">低代码表单与记录 <a class="header-anchor" href="#低代码表单与记录" aria-label="Permalink to &quot;低代码表单与记录&quot;">​</a></h1><p>入口为 <strong>通用能力 → 表单管理</strong>（<code>/lowcode/forms</code>）。平台设计身份配合 <code>lowcode:form:list/query/add/edit/publish/remove</code>；填写/记录使用 <code>lowcode:record:list/query/add/edit/remove</code>。普通租户拥有记录权限可以使用已发布schema，不能修改平台设计。</p><h2 id="设计、预览和发布" tabindex="-1">设计、预览和发布 <a class="header-anchor" href="#设计、预览和发布" aria-label="Permalink to &quot;设计、预览和发布&quot;">​</a></h2><ol><li>点击“新增表单”，在“表单名称”填写“需求登记”，“表单标识”填写 <code>request_register</code>。标识是小写字母开头的稳定名称，创建后不能改。</li><li>选择第一个字段，将“字段标识”设为 <code>subject</code>、“显示名称”设为“需求主题”；“字段类型”选“单行文本”，开启“必填”。点击“添加字段”，把第二项显示名称设为“补充说明”、标识设为 <code>description</code>，类型选“多行文本”。用“上移/下移”调整顺序，用“移除”删除尚未需要的字段。</li><li>点击“预览填写”，空着主题点击“验证填写”，应看到必填提示；填写“改善列表筛选”，再次验证应通过。预览不会保存业务记录。</li><li>关闭预览，点击“保存草稿”，再使用列表“发布”，或在设计器点击“保存并发布”并确认。列表应显示已启用和发布版本1；单独保存草稿不让填写页切换版本。</li></ol><p>字段还可设置“字段帮助”、默认值、“列表显示”和“允许查询”；每项设置的技术字段及限制见下表和<a href="/xinghui-admin-vue3/docs/development/lowcode-extension.html">Schema扩展</a>。</p><table tabindex="0"><thead><tr><th>类型</th><th>限制</th></tr></thead><tbody><tr><td>text / textarea</td><td>默认200 / 5000字符，上限2000 / 5000</td></tr><tr><td>number</td><td>绝对值≤1e12、小数最多6位，可设min/max</td></tr><tr><td>date</td><td>真实YYYY-MM-DD日期</td></tr><tr><td>select / multiselect</td><td>1–100选项，value支持0/1等非空ASCII字母数字下划线连字符；多选不支持查询条件</td></tr><tr><td>switch</td><td>真正boolean，false可以是有效必填值</td></tr></tbody></table><p>最多100字段；fieldKey最长50，不能覆盖ID、tenant、creator、revision等系统字段。schema与data各最多256KiB UTF-8 JSON。当前没有字段联动、公式、附件、流程或匿名公开填写。</p><h2 id="填写与管理" tabindex="-1">填写与管理 <a class="header-anchor" href="#填写与管理" aria-label="Permalink to &quot;填写与管理&quot;">​</a></h2><p>从表单列表打开 <code>/lowcode/runtime/{formId}</code> 填写、<code>/lowcode/records/{formId}</code> 管理。新提交带当前published schemaVersion；数据页按配置显示列和查询条件，详情/编辑使用记录原schemaVersion。停用阻止新增，历史记录仍可按权限编辑。</p><p>继续上例：点击该行“填写”，输入主题“改善列表筛选”和说明“增加状态过滤”，点击“提交记录”。页面显示“记录已保存”及编号；有列表权限时点击“数据列表”，应看到这条记录及填写版本1。点击“编辑”修改说明、保存，再刷新核对；点击“详情”只读查看，删除前确认具体记录。这个例子只在有权限且已授权的测试环境中操作，不要求创建新的业务模块。</p><p>普通租户可由管理员提供填写/数据深链，不需要表单设计列表权限。服务端runtime读取允许record五种权限任一种，填写页面仍要求add、数据列表要求list、详情要求query，编辑/删除各自授权。记录按tenant范围，不按creator限定为“仅本人”。</p><p>已有记录使用过的字段key/type不能删除或改变，包含软删除记录；允许兼容新增或修改标签/展示。发布失败时已保存草稿保留，先修复兼容性，不清空数据强行发布。record读写始终联合当前tenant、formId、recordId，不能仅凭recordId访问其他租户或表单。</p><h2 id="结果与恢复" tabindex="-1">结果与恢复 <a class="header-anchor" href="#结果与恢复" aria-label="Permalink to &quot;结果与恢复&quot;">​</a></h2><p>保存后重新读取确认持久化；成功提交后再选择继续填写，避免重复数据。版本冲突先保留输入再重新读取；旧schemaVersion的新建请求拒绝。记录删除需要revision；存在历史记录的表单不能删除。没有读取权限不能直调API，隐藏按钮不替代后端检查。</p><h2 id="ai记录摘要" tabindex="-1">AI记录摘要 <a class="header-anchor" href="#ai记录摘要" aria-label="Permalink to &quot;AI记录摘要&quot;">​</a></h2><p>摘要复用现有表单记录及读取权限，配置见<a href="/xinghui-admin-vue3/docs/features/ai.html">提示词配置与业务摘要</a>。管理员在提示词配置中选择表单、允许字段和模型，合法保存后供新调用使用。首个内置来源仅允许subject/summary与实际schema的交集；旧映射还受原批准资源范围限制。管理配置权不代表记录读取或业务调用权。</p><p>新工作区仍待组合验收。此前一期真实模型、SSE、日志及采纳保存刷新证据按<a href="./../releases/versions.html">版本配对</a>记录，不能当作新工作区已部署。记录入口按当前有效场景和真实权限判断可用性，不要求填写应用ID或模板版本；静态演示不连接真实供应商。</p><p>用户填写摘要要求后生成，可取消、查询原请求或复制当前内容。服务端重新读取记录，保持原schemaVersion及类型/null，当前列表正文不是模型取数来源。受理、部分输出或连接断开不代表成功；刷新查询原状态，正文未保存且短期事件过期时不能恢复，也不自动重发。</p><p>完整成功结果配合记录编辑权限，可选择长度合适的text/textarea字段“填入编辑草稿”。页面重新读取记录，用户检查后仍须点击原表单保存才入库。失败、超时或中断结果不能自动写入记录。Agent审批写、插件执行和持久会话尚未交付。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/views/lowcode/form-schema.ts</code>、<code>RuntimeFields.vue</code>、<code>forms/FormDesigner.vue</code>，API <code>apps/web-ele/src/api/lowcode/forms.ts</code>。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/lowcode/LowcodeSchema.java</code>、<code>LowcodeService.java</code>、<code>LowcodeIdentity.java</code>（同目录）。</li><li>固定三表：<code>system-admin/src/main/resources/db/migration/V20261012_160__lowcode_forms.sql</code>。</li></ul>',21)])])}const p=o(r,[["render",c]]);export{u as __pageData,p as default};
